<script lang="ts">
	// Slots:
	/** @slot trail - A label slot directly below the range slider. */

	// Types
	import type { CssClasses } from '../../index.js';

	// Props (a11y)

	interface Props {
		class?: string;
		onclick?: ((event: MouseEvent) => void) | undefined;
		onchange?: ((event: Event) => void) | undefined;
		onblur?: ((event: FocusEvent) => void) | undefined;
		/** Required. Set a unique name for the input. */
		name: string;
		/** Provide a unique input id. Auto-generated by default */
		id?: any;
		/** Set the input value. */
		value?: number;
		/** Set the input minimum range. */
		min?: number;
		/** Set the input maximum range. */
		max?: number;
		/** Set the input step offset. */
		step?: number;
		/** Enables tick marks. See browser support below. */
		ticked?: boolean;
		/** Provide classes to set the input accent color. */
		accent?: CssClasses;
		/** A semantic ARIA label. */
		label?: string;
		children?: import('svelte').Snippet;
		trail?: import('svelte').Snippet;
		[key: string]: any;
	}

	let {
		class: className = '',
		onclick = undefined,
		onchange = undefined,
		onblur = undefined,
		name,
		id = String(Math.random()),
		value = $bindable(0),
		min = 0,
		max = 100,
		step = 1,
		ticked = false,
		accent = 'accent-surface-900 dark:accent-surface-50',
		label = '',
		children,
		trail,
		...rest
	}: Props = $props();

	// Base Styles
	const cBase = 'space-y-2';
	const cBaseLabel = '';
	const cBaseContent = 'flex justify-center py-2';
	const cBaseInput = 'w-full h-2';

	// Local
	let tickmarks = $derived(ticked ? Array.from({ length: max - min + 1 }, (_, i) => i + min) : []);

	// Reactive Classes
	let classesBase = $derived(`${cBase} ${className ?? ''}`);
	let classesInput = $derived(`${cBaseInput} ${accent}`);

	// Prune $$restProps to avoid overwriting className
	function prunedRestProps() {
		return rest;
	}
</script>

<div class="range-slider {classesBase}" data-testid="range-slider">
	<!-- Slot: Default -->
	{#if children}<label class="range-slider-label {cBaseLabel}" for={id}>{@render children?.()}</label>{/if}

	<!-- Content -->
	<div class="range-content {cBaseContent}">
		<!-- Input -->
		<input
			type="range"
			{id}
			{name}
			class="range-slider-input {classesInput}"
			list="tickmarks-{id}"
			aria-label={label}
			{min}
			{max}
			{step}
			bind:value
			onclick={(event) => onclick?.(event)}
			onchange={(event) => onchange?.(event)}
			onblur={(event) => onblur?.(event)}
			{...prunedRestProps()}
		/>

		<!-- Tickmarks -->
		{#if ticked && tickmarks && tickmarks.length}
			<datalist id="tickmarks-{id}" class="range-slider-ticks">
				{#each tickmarks as tm}
					<option value={tm} label={String(tm)}></option>
				{/each}
			</datalist>
		{/if}
	</div>

	<!-- Slot: Trail -->
	{#if trail}<div class="range-slider-trail">{@render trail?.()}</div>{/if}
</div>
